document.addEventListener('DOMContentLoaded', function() {
  var menuBtn = document.querySelector('.menu-button-mobile');
  var menuNav = document.getElementById('user-nav-mobile');

  if (menuBtn && menuNav) {
    menuBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      var isOpen = menuNav.style.display === 'block';

      if (isOpen) {
        menuNav.style.display = 'none';
      } else {
        menuNav.style.display = 'block';
        menuNav.style.position = 'fixed';
        menuNav.style.top = '56px';
        menuNav.style.left = '0';
        menuNav.style.right = '0';
        menuNav.style.bottom = '0';
        menuNav.style.backgroundColor = '#0a0a0a';
        menuNav.style.zIndex = '999999';
        menuNav.style.overflowY = 'auto';
        menuNav.style.padding = '8px 0';
        menuNav.style.borderTop = 'none';

        // Style all child elements
        var allElements = menuNav.querySelectorAll('*');
        allElements.forEach(function(el) {
          el.style.backgroundColor = '#0a0a0a';
        });

        // Style links
        var links = menuNav.querySelectorAll('a');
        links.forEach(function(link) {
          link.style.color = '#ccc';
          link.style.display = 'block';
          link.style.padding = '16px 24px';
          link.style.fontSize = '16px';
          link.style.textDecoration = 'none';
          link.style.backgroundColor = '#0a0a0a';
        });

        // Style buttons
        var buttons = menuNav.querySelectorAll('button');
        buttons.forEach(function(btn) {
          btn.style.color = '#ccc';
          btn.style.display = 'block';
          btn.style.padding = '16px 24px';
          btn.style.fontSize = '16px';
          btn.style.backgroundColor = '#0a0a0a';
          btn.style.width = '100%';
          btn.style.textAlign = 'left';
          btn.style.border = 'none';
        });

        // Style dividers
        var dividers = menuNav.querySelectorAll('.nav-divider');
        dividers.forEach(function(div) {
          div.style.borderBottomColor = '#222';
          div.style.backgroundColor = '#0a0a0a';
        });

        // Style list items
        var items = menuNav.querySelectorAll('li');
        items.forEach(function(item) {
          item.style.backgroundColor = '#0a0a0a';
        });

        // Style the ul
        var ul = menuNav.querySelector('ul');
        if (ul) {
          ul.style.backgroundColor = '#0a0a0a';
        }
      }
    });
  }
});
(function () {
    var el = document.documentElement;
    var fallback = 'dark' === 'light' ? 'light' : 'dark';
    var mode = fallback;
    try {
      var stored = window.localStorage.getItem('nzxt-color-mode');
      if (stored === 'light' || stored === 'dark') {
        mode = stored;
      } else if (true &&
                 window.matchMedia &&
                 window.matchMedia('(prefers-color-scheme: light)').matches) {
        mode = 'light';
      }
    } catch (e) {
      /* Private browsing or blocked storage: fall through to the default. */
    }
    el.setAttribute('data-theme', mode);
  })();
